/**
 * Extract the DSH Desktop WebUI design system into a standalone stylesheet.
 *
 * The DSH web frontend ships its palette inside `@deepseek-ai/dsh-client-ui-theme`
 * as CSS string literals held in the client bundle. This script pulls those
 * literals out, keeps the design-token and base-layer rules, and writes them to
 * `src/renderer/styles/tokens.css` so the plain (non-glass) theme is a faithful
 * port of DSH's WebUI rather than an approximation.
 *
 * Usage:
 *   node scripts/extract-dsh-tokens.mjs "<path to dsh-client-ui-theme/lib/client.js>"
 *
 * The generated file is committed; re-run only when refreshing from a newer
 * DSH Desktop build.
 */

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const target = path.join(here, '..', 'src', 'renderer', 'styles', 'tokens.css')

const source =
  process.argv[2] ??
  'C:/Program Files/DSH Desktop/resources/app.asar.unpacked/node_modules/@deepseek-ai/dsh-client-ui-theme/lib/client.js'

/** Pull every double-quoted string literal that looks like CSS in a JS bundle. */
function extractCssStrings(src) {
  const out = []
  let i = 0
  while (i < src.length) {
    if (src[i] !== '"') {
      i += 1
      continue
    }
    let j = i + 1
    let buf = ''
    while (j < src.length) {
      const ch = src[j]
      if (ch === '\\') {
        const nx = src[j + 1]
        if (nx === '"') buf += '"'
        else if (nx === 'n') buf += '\n'
        else if (nx === 't') buf += '\t'
        else if (nx === '\\') buf += '\\'
        else buf += nx
        j += 2
        continue
      }
      if (ch === '"' || ch === '\n') break
      buf += ch
      j += 1
    }
    if (src[j] === '"' && buf.includes('--dsw-') && buf.includes('{') && buf.includes('}')) {
      out.push(buf)
    }
    i = j + 1
  }
  return out
}

/** Split a stylesheet into top-level rules, ignoring braces inside values. */
function topLevelRules(css) {
  const rules = []
  let depth = 0
  let start = 0
  for (let i = 0; i < css.length; i++) {
    const ch = css[i]
    if (ch === '{') depth += 1
    else if (ch === '}') {
      depth -= 1
      if (depth === 0) {
        rules.push(css.slice(start, i + 1))
        start = i + 1
      }
    }
  }
  return rules
}

/**
 * Rules we keep: the token layers (:root / body / dark override) plus the base
 * reset, scrollbar and focus-ring rules. Component-scoped hashed class names
 * from DSH's own settings widgets are dropped — they style components that do
 * not exist in this app.
 */
const KEEP = [
  /^:root\b/,
  /^body$/,
  /^body\[data-ds-dark-theme\]$/,
  /^html\[data-platform=/,
  /^\*,:before,:after$/,
  /^body,body \*$/,
  /^::-webkit-scrollbar/,
  /^:focus-visible$/,
  /^\[data-dsh-automatic-focus\]/,
  /^html\[data-input-modality=pointer\] body :focus-visible/,
]

const css = extractCssStrings(fs.readFileSync(source, 'utf8')).join('\n')
const kept = []
const seen = new Set()
for (const rule of topLevelRules(css)) {
  const selector = rule.slice(0, rule.indexOf('{')).trim()
  if (!KEEP.some((re) => re.test(selector))) continue
  if (seen.has(rule)) continue
  seen.add(rule)
  kept.push(rule)
}

const banner = `/*
 * DSH Desktop WebUI design tokens — extracted verbatim from
 * @deepseek-ai/dsh-client-ui-theme (DSH Desktop build).
 *
 * Generated by scripts/extract-dsh-tokens.mjs — do not edit by hand.
 *
 * Layers:
 *   :root                      typography, focus ring geometry
 *   :root / body               static palette + light alias set
 *   body[data-ds-dark-theme]   dark alias set
 *
 * The app mirrors DSH's own convention: dark mode is signalled by adding the
 * \`data-ds-dark-theme\` attribute to <body>, which is exactly what the
 * bootstrap script in DSH does.
 *
 * ${kept.length} rules.
 */

`

fs.mkdirSync(path.dirname(target), { recursive: true })
fs.writeFileSync(target, banner + kept.join('\n') + '\n', 'utf8')
console.log(`wrote ${target} (${kept.length} rules, ${(banner + kept.join('\n')).length} bytes)`)
